use std::fs
use std::json
use std::process

struct Item {
    sku: string,
    qty: int,
    price: float,
}

struct Order {
    id: int,
    customer: string,
    items: Vec<Item>,
    note: Option<string>,
}

fn main() {
    let text = fs::read_to_string("/dev/stdin").unwrap_or("")
    let parsed = json.parse_string::<Vec<Order>>(text)
    match parsed {
        Ok(orders) => {
            let mut names: Vec<string> = []
            let mut totals: Vec<float> = []
            for o in orders {
                let mut idx: int = -1
                let mut i: int = 0
                while i < names.len() as int {
                    if names[i as usize] == o.customer { idx = i }
                    i += 1
                }
                if idx < 0 {
                    names.push(o.customer)
                    totals.push(0.0)
                    idx = names.len() as int - 1
                }
                let mut s: float = 0.0
                for it in o.items {
                    s += (it.qty as float) * it.price
                }
                totals[idx as usize] += s
            }
            let mut order: Vec<int> = []
            let mut k: int = 0
            while k < names.len() as int {
                order.push(k)
                k += 1
            }
            order.sort_by(|a, b| names[*a as usize].cmp(&names[*b as usize]))
            for j in order {
                println("${names[j as usize]} ${totals[j as usize]:.2}")
            }
        }
        Err(_) => {
            println("invalid input")
            process::exit(1)
        }
    }
}

